// يحسب مقدار الحفظ/المراجعة (صفحات + أسطر) لمقطع من سورة معيّنة، من آية إلى آية
// القاعدة: كل 15 سطراً = صفحة واحدة (حسب طلب المستخدم)، محسوبة من مواضع الآيات
// الفعلية بالمصحف المدني ذي الخمسة عشر سطراً، فتُعطي نتيجة مطابقة لعدّ حقيقي
// بالمصحف الورقي وليست تقريبية.
// ترجع null إن كانت السورة/الآية غير موجودة بالفهرس (خطأ إدخال محتمل)
function computeQuranSpan(surahNum, fromAyah, toAyah){
  const list = QURAN_MUSHAF_DATA.bySurah[String(surahNum)];
  if(!list) return null;
  const from = list.find(x=>x[0]===Number(fromAyah));
  const to   = list.find(x=>x[0]===Number(toAyah));
  if(!from || !to) return null;
  const startLine = Math.min(from[1], to[1]);
  const endLine   = Math.max(from[2], to[2]);
  const totalLines = endLine - startLine + 1;
  const pages = Math.floor(totalLines / QURAN_MUSHAF_DATA.linesPerPageNominal);
  const remLines = totalLines % QURAN_MUSHAF_DATA.linesPerPageNominal;
  return { totalLines, pages, remLines };
}

// نص مختصر لعرض النتيجة، مثال: "صفحة و3 أسطر" أو "صفحتان" أو "5 أسطر"
function formatQuranSpan(span){
  if(!span) return '';
  const {pages, remLines} = span;
  const parts=[];
  if(pages===1) parts.push('صفحة واحدة');
  else if(pages===2) parts.push('صفحتان');
  else if(pages>2) parts.push(pages+' صفحات');
  if(remLines===1) parts.push('سطر واحد');
  else if(remLines>0) parts.push(remLines+' أسطر');
  return parts.length?parts.join(' و'):'أقل من سطر';
}
